const response = $input.first().json;
const subscribers = response.subscribers || [];

const themeData = $('Lire Thème du Mois').first().json;
const theme = themeData.theme || 'Aventure du mois';
const monthLabel = themeData.monthLabel || new Date().toLocaleDateString('fr-FR', {month:'long', year:'numeric'});

if (subscribers.length === 0) {
  throw new Error('Aucun abonné actif trouvé. Ajoutez des abonnés via WF4.');
}

return subscribers.map(sub => ({
  json: { ...sub, theme, monthLabel }
}));

const sub = $('Split Abonnés').item.json;
const histResp = $input.first().json;
const history = histResp.history || [];

const historyText = history.length === 0
  ? 'Aucune histoire précédente pour cet abonné.'
  : history.map((h, i) => `${i + 1}. "${h.titre}" — Thème : ${h.theme} (${h.monthLabel}) — ${h.resume}`).join('\n');

return [{ json: { ...sub, storyHistory: history, storyHistoryText: historyText } }];

parameters.text:
=Voici une commande abonnement mensuel Livre&Vous :

--- THÈME DU MOIS ---
Thème : {{ $json.theme }}
Mois : {{ $json.monthLabel }}

--- HISTOIRES PRÉCÉDENTES DE CET ABONNÉ (À NE PAS RÉPÉTER) ---
{{ $json.storyHistoryText }}

⚠️ La nouvelle histoire doit avoir une trame, des décors et une aventure ENTIÈREMENT DIFFÉRENTS de ceux listés ci-dessus.

--- PERSONNAGE PRINCIPAL ---
Prénom : {{ $json.prenom }}
Âge : {{ $json.age }}
Genre : {{ $json.genre }}
Coupe : {{ $json.coupe }}
Couleur cheveux : {{ $json.couleur }}
Couleur yeux : {{ $json.yeux }}

--- PERSONNAGE SECONDAIRE ---
Présent : {{ $json.hasSecondChar ? 'Oui' : 'Non' }}
Prénom : {{ $json.prenom2 || '' }}
Âge : {{ $json.age2 || '' }}
Genre : {{ $json.genre2 || '' }}
Lien : {{ $json.lien2 || '' }}
Coupe : {{ $json.coupe2 || '' }}
Couleur cheveux : {{ $json.couleur2 || '' }}
Couleur yeux : {{ $json.yeux2 || '' }}

L'histoire DOIT être entièrement basée sur le thème du mois et adaptée à l'âge de l'enfant. Génère exactement 15 pages.

