let output = $input.item.json.output;
output = output.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(output);
} catch(e) {
  try {
    output = output.replace(/:\s*"((?:[^"\\]|\\.)*)"/gs, (match, p1) => {
      const cleaned = p1.replace(/(?<!\\)"/g, '\\"');
      return `: "${cleaned}"`;
    });
    parsed = JSON.parse(output);
  } catch(e2) {
    const titreMatch = output.match(/"titre":\s*"([^"]+)"/);
    const prenomMatch = output.match(/"prenom":\s*"([^"]+)"/);
    const resumeMatch = output.match(/"resume":\s*"([^"]+)"/);
    parsed = {
      titre: titreMatch?.[1] || 'Mon aventure',
      prenom: prenomMatch?.[1] || '',
      resume: resumeMatch?.[1] || '',
      pages: []
    };
  }
}

const sub = $('Split Abonnés').item.json;

const prenom = sub.prenom || '';
const imageRef = sub.imageRef || '';
const imageRef2 = sub.imageRef2 || '';
const hasSecondChar = sub.hasSecondChar || false;

const coverNote = 'IMPORTANT: characters must be in the BOTTOM RIGHT area of the image, larger than usual — filling about 40% of the image height. The TOP 20% of the right side is reserved for logo overlay — keep it completely clear of any characters or important elements. Characters must be fully visible but their head must not exceed 80% from the top of the image. Left half and center must show background and decor only. Bright colorful scene, blue or golden sky, vivid cheerful colors, warm sunlight. ';

return parsed.pages.slice(0, 15).map(page => {
  const isPage1 = (page.numero || page.page) === 1;
  return {
    json: {
      page: page.numero || page.page,
      texte: page.texte_page || page.texte || '',
      imageRef,
      imageRef2,
      hasSecondChar,
      prompt: `3D Pixar CGI animation style, Disney-Pixar quality render, children book illustration, wide scene. ${isPage1 ? coverNote : ''}${page.prompt_illustration || page.prompt || ''}. REFERENCE IMAGE IS THE ONLY SOURCE FOR CHARACTER APPEARANCE: replicate exactly the character's face, hair color and style, skin tone, clothing, shoes and accessories from the reference image — do not invent or modify any physical feature or clothing item. Full image filled with rich immersive background and environment from top to bottom — no empty zones, no blank areas. Character stands naturally in the lower portion of the scene, large and prominent. Character's head stays below the upper 30% of the image. Character positioned in left or right third, never centered. Natural warm lighting, balanced exposure, sunny or softly cloudy. No additional people in the scene. No text, signs or letters anywhere. Safe and joyful content for children. Smooth 3D textures, wide angle view, no photorealism.`,
      prenom,
      titre: parsed.titre,
      resume: parsed.resume,
      dedicace: sub.theme || '',
      email: sub.email || '',
      firstName: sub.firstName || '',
      lastName: sub.lastName || '',
      address1: sub.address1 || '',
      address2: sub.address2 || '',
      city: sub.city || '',
      postcode: sub.postcode || '',
      country: sub.country || 'FR',
      phone: sub.phone || '',
      customerId: sub.customerId || '',
      orderId: sub.orderId || sub.email || '',
      genre: sub.genre || '',
      couverture: sub.couverture || 'Rigide - 20x20 cm',
      theme: sub.theme || '',
      monthLabel: sub.monthLabel || ''
    }
  };
});

const item = $input.first().json;

const uploads = [{
  json: {
    fileUrl: item.imageRef,
    uploadPath: 'images',
    fileName: `ref1_${Date.now()}.png`,
    isMain: true,
    originalData: item
  }
}];

if (item.hasSecondChar && item.imageRef2) {
  uploads.push({
    json: {
      fileUrl: item.imageRef2,
      uploadPath: 'images',
      fileName: `ref2_${Date.now()}.png`,
      isMain: false,
      originalData: item
    }
  });
}

return uploads;

const uploads = $input.all();
const pages = $('Parser Histoire').all();

const kieRef1 = uploads[0]?.json?.data?.downloadUrl || '';
const kieRef2 = uploads[1]?.json?.data?.downloadUrl || '';

return pages.map(page => {
  const imageInput = [kieRef1];
  if (kieRef2) imageInput.push(kieRef2);

  return {
    json: {
      ...page.json,
      kieBody: JSON.stringify({
        model: 'nano-banana-2',
        input: {
          prompt: page.json.prompt,
          image_input: imageInput,
          aspect_ratio: '16:9',
          resolution: '1K',
          output_format: 'png'
        }
      })
    }
  };
});

const results = $input.all();
const taskData = $('Stocker Task IDs').all();

const taskMap = {};
taskData.forEach(item => { taskMap[item.json.taskId] = item.json; });

return results.map((item, index) => {
  const data = item.json.data;
  const success = data?.state === 'success' && data?.resultJson && data?.resultJson !== '';
  const imageUrl = success ? JSON.parse(data.resultJson).resultUrls?.[0] || '' : '';
  const pageData = taskMap[data?.taskId] || taskData[index]?.json || {};

  return {
    json: {
      page: pageData.page || index + 1,
      texte: pageData.texte || '',
      prompt: pageData.prompt || '',
      kieBody: pageData.kieBody || '',
      prenom: pageData.prenom || '',
      titre: pageData.titre || '',
      resume: pageData.resume || '',
      imageRef: pageData.imageRef || '',
      imageRef2: pageData.imageRef2 || '',
      email: pageData.email || '',
      firstName: pageData.firstName || '',
      lastName: pageData.lastName || '',
      address1: pageData.address1 || '',
      address2: pageData.address2 || '',
      city: pageData.city || '',
      postcode: pageData.postcode || '',
      country: pageData.country || 'FR',
      phone: pageData.phone || '',
      customerId: pageData.customerId || '',
      orderId: pageData.orderId || '',
      genre: pageData.genre || '',
      couverture: pageData.couverture || 'Rigide - 20x20 cm',
      dedicace: pageData.dedicace || '',
      theme: pageData.theme || '',
      monthLabel: pageData.monthLabel || '',
      taskId: data?.taskId,
      imageUrl,
      failed: !success
    }
  };
});

const newResults = $input.all();
const oldResults = $('Analyser Résultats').all();
const taskData = $('Stocker Retry IDs').all();

const taskMap = {};
taskData.forEach(item => { taskMap[item.json.taskId] = item.json; });

const retriedMap = {};
newResults.forEach(item => {
  const data = item.json.data;
  const success = data?.state === 'success' && data?.resultJson && data?.resultJson !== '';
  const imageUrl = success ? JSON.parse(data.resultJson).resultUrls?.[0] || '' : '';
  const pageData = taskMap[data?.taskId];
  if (pageData) {
    retriedMap[pageData.page] = {
      json: { ...pageData, taskId: data?.taskId, imageUrl, failed: !success }
    };
  }
});

return oldResults.map(item => {
  const retried = retriedMap[item.json.page];
  if (retried) return retried;
  return item;
});

const pollingResults = $input.all();
const allCheckResults = $('Analyser Résultats').all();

const hasFailed = allCheckResults.some(i => i.json.failed);
if (hasFailed && pollingResults.length < allCheckResults.length) {
  return [];
}

return pollingResults.map(item => ({
  json: {
    page: item.json.page,
    texte: item.json.texte,
    imageUrl: item.json.imageUrl,
    kieBody: item.json.kieBody || '',
    imageRef: item.json.imageRef || '',
    imageRef2: item.json.imageRef2 || '',
    prenom: item.json.prenom,
    titre: item.json.titre,
    resume: item.json.resume,
    email: item.json.email || '',
    firstName: item.json.firstName || '',
    lastName: item.json.lastName || '',
    address1: item.json.address1 || '',
    address2: item.json.address2 || '',
    city: item.json.city || '',
    postcode: item.json.postcode || '',
    country: item.json.country || 'FR',
    phone: item.json.phone || '',
    customerId: item.json.customerId || '',
    orderId: item.json.orderId || '',
    genre: item.json.genre || '',
    couverture: item.json.couverture || 'Rigide - 20x20 cm',
    dedicace: item.json.dedicace || '',
    theme: item.json.theme || '',
    monthLabel: item.json.monthLabel || ''
  }
}));

const pages = $input.all();
const pagesJson = pages.map(p => ({
  page: p.json.page,
  texte: p.json.texte,
  imageUrl: p.json.imageUrl,
  kieBody: p.json.kieBody || '',
  imageRef: p.json.imageRef || '',
  imageRef2: p.json.imageRef2 || ''
}));

const first = pages[0].json;

const genre = (first.genre || '').toLowerCase();
const remerciementUrl = (genre === 'fille' || genre === 'girl' || genre === 'f')
  ? 'https://res.cloudinary.com/daevhiitx/image/upload/v1777104214/2_ewr756.png'
  : 'https://res.cloudinary.com/daevhiitx/image/upload/v1777104214/1_ov5ysc.png';

let productUid = '';
const couverture = first.couverture || 'Rigide - 20x20 cm';
if (couverture === 'Rigide - 20x20 cm') {
  productUid = 'photobooks-hardcover_pf_200x200-mm-8x8-inch_pt_170-gsm-65lb-coated-silk_cl_4-4_ccl_4-4_bt_glued-left_ct_matt-lamination_prt_1-0_cpt_130-gsm-65-lb-cover-coated-silk_ver';
} else if (couverture === 'Souple - 20x20 cm') {
  productUid = 'photobooks-softcover_pf_200x200-mm-8x8-inch_pt_170-gsm-65lb-coated-silk_cl_4-4_ccl_4-4_bt_glued-left_ct_matt-lamination_prt_1-0_cpt_250-gsm-100-lb-cover-coated-silk_ver';
} else if (couverture === 'Souple - 14x14 cm') {
  productUid = 'photobooks-softcover_pf_140x140-mm-5_5x5_5-inch_pt_170-gsm-65lb-coated-silk_cl_4-4_ccl_4-4_bt_glued-left_ct_matt-lamination_prt_1-0_cpt_250-gsm-100-lb-cover-coated-silk_ver';
}

const orderRef = `ABO-${first.orderId || first.email}-${Date.now()}`;
const coverImageUrl = pagesJson.length > 0 ? pagesJson[0].imageUrl || '' : '';

const bookData = {
  orderRef,
  prenom: first.prenom || '',
  titre: first.titre || '',
  resume: first.resume || '',
  dedicace: first.dedicace || '',
  theme: first.theme || '',
  monthLabel: first.monthLabel || '',
  couverture,
  productUid,
  remerciementUrl,
  firstName: first.firstName || '',
  lastName: first.lastName || '',
  email: first.email || '',
  address1: first.address1 || '',
  address2: first.address2 || '',
  city: first.city || '',
  postcode: first.postcode || '',
  country: first.country || 'FR',
  phone: first.phone || '',
  customerId: first.customerId || '',
  originalImageUrls: pagesJson.map(p => p.imageUrl),
  pages: pagesJson
};

const dataB64 = Buffer.from(JSON.stringify(bookData)).toString('base64');

return [{
  json: {
    dataB64,
    orderRef,
    prenom: bookData.prenom,
    titre: bookData.titre,
    resume: bookData.resume,
    couverture,
    coverImageUrl,
    totalPages: pagesJson.length,
    email: bookData.email,
    firstName: bookData.firstName,
    theme: bookData.theme,
    monthLabel: bookData.monthLabel
  }
}];
